<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
class CandidateAccountController extends Controller{public function export(Request $r):JsonResponse{$u=$r->user()->load(['candidateProfile.educations','candidateProfile.languages','candidateProfile.documents','candidateProfile.languageAssessments','candidateProfile.jobApplications.offer','complaints','subscriptions']);return response()->json(['exported_at'=>now(),'user'=>$u]);}public function destroy(Request $r):JsonResponse{$u=$r->user();$u->update(['deletion_requested_at'=>now()->addDays(30),'status'=>'blocked','status_reason'=>'Account deletion requested','status_changed_at'=>now()]);$u->tokens()->delete();return response()->json(['deletion_scheduled_at'=>$u->deletion_requested_at]);}public function cancel(Request $r):JsonResponse{$u=$r->user();$u->update(['deletion_requested_at'=>null,'status'=>'active','status_reason'=>null,'status_changed_at'=>now()]);return response()->json(['cancelled'=>true]);}}
